import{_ as t,o as a,c as r,a3 as c}from"./chunks/framework.DAK02U1-.js";const m=JSON.parse('{"title":"LLVM Patches","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"LLVM Patches | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/xclang/reference/patches"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/xclang/reference/patches"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/reference/patches"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/reference/patches"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/xclang/reference/patches"}]]},"headers":[],"relativePath":"xclang/reference/patches.md","filePath":"en/xclang/reference/patches.md","lastUpdated":1794509097000}'),o={name:"xclang/reference/patches.md"};function i(s,e,n,l,d,h){return a(),r("div",null,[...e[0]||(e[0]=[c('<h1 id="llvm-patches" tabindex="-1">LLVM Patches <a class="header-anchor" href="#llvm-patches" aria-label="Permalink to &quot;LLVM Patches&quot;">​</a></h1><p>xclang builds its compiler, linkers, runtimes and libclang from LLVM&#39;s release source, <code>llvm-project-&lt;version&gt;.src.tar.xz</code>, with the changes in <a href="https://github.com/clice-io/xclang/tree/main/patches" target="_blank" rel="noreferrer"><code>patches/</code></a>. Each patch&#39;s README says what goes wrong without it, what it changes, how it was checked and where it stands upstream.</p><h2 id="patches" tabindex="-1">Patches <a class="header-anchor" href="#patches" aria-label="Permalink to &quot;Patches&quot;">​</a></h2><table tabindex="0"><thead><tr><th>patch</th><th>what it changes</th></tr></thead><tbody><tr><td><a href="https://github.com/clice-io/xclang/blob/main/patches/0001-sema-partial-ordering-depth/README.md" target="_blank" rel="noreferrer"><code>0001-sema-partial-ordering-depth</code></a></td><td>partial ordering deduces at the templates&#39; own depth: code completion in a class template no longer crashes clang (<a href="https://github.com/clice-io/clice/issues/701" target="_blank" rel="noreferrer">clice#701</a>)</td></tr><tr><td><a href="https://github.com/clice-io/xclang/blob/main/patches/0002-completion-unresolved-member-base/README.md" target="_blank" rel="noreferrer"><code>0002-completion-unresolved-member-base</code></a></td><td>member-access completion reports its context when Sema finds no class for the base</td></tr><tr><td><a href="https://github.com/clice-io/xclang/blob/main/patches/0003-completion-context-base-expr/README.md" target="_blank" rel="noreferrer"><code>0003-completion-context-base-expr</code></a></td><td><code>CodeCompletionContext::getBaseExpr</code>, the member base as written</td></tr><tr><td><a href="https://github.com/clice-io/xclang/blob/main/patches/0004-windows-driver-setup-api-mingw/README.md" target="_blank" rel="noreferrer"><code>0004-windows-driver-setup-api-mingw</code></a></td><td>the MinGW-built clang finds Visual Studio 2017 and later through the Setup API, like the MSVC-built one (<a href="https://github.com/clice-io/clice/issues/714" target="_blank" rel="noreferrer">clice#714</a>)</td></tr><tr><td><a href="https://github.com/clice-io/xclang/blob/main/patches/0007-lld-macho-empty-section-unwind/README.md" target="_blank" rel="noreferrer"><code>0007-lld-macho-empty-section-unwind</code></a></td><td>ld64.lld keeps a function&#39;s unwind entry when an empty section&#39;s symbol shares its address: ThinLTO programs linked by one clang command catch their exceptions on arm64 macOS</td></tr><tr><td><a href="https://github.com/clice-io/xclang/blob/main/patches/0008-preprocessed-raw-string-lines/README.md" target="_blank" rel="noreferrer"><code>0008-preprocessed-raw-string-lines</code></a></td><td><code>clang -E</code> writes a raw string literal&#39;s CRLF line breaks as <code>\\n</code>, what they mean, and counts its lines: its output, compiled (build caches such as xmake&#39;s), gives the same strings and line numbers</td></tr><tr><td><a href="https://github.com/clice-io/xclang/blob/main/patches/0010-windows-stack-trace/README.md" target="_blank" rel="noreferrer"><code>0010-windows-stack-trace</code></a></td><td>crash stack traces on arm64 Windows go past system DLL frames, whose return addresses are signed: a crash in a C library callback, or a trace printed from a signal handler, reaches the code that crashed</td></tr><tr><td><a href="https://github.com/clice-io/xclang/blob/main/patches/0011-clang-cl-config-pass-through/README.md" target="_blank" rel="noreferrer"><code>0011-clang-cl-config-pass-through</code></a></td><td>clang-cl reports no option of a config file unused, also those it passes through with <code>/clang:</code>: the MSVC targets&#39; C compiles with <code>/WX</code></td></tr><tr><td><a href="https://github.com/clice-io/xclang/blob/main/patches/0012-msvc-compiler-rt-libpath-first/README.md" target="_blank" rel="noreferrer"><code>0012-msvc-compiler-rt-libpath-first</code></a></td><td>clang links MSVC targets with its own compiler-rt ahead of Visual Studio&#39;s <code>clang_rt.*.lib</code>: without a fetched SDK, <code>__int128</code> division, UBSan and libFuzzer link</td></tr><tr><td><a href="https://github.com/clice-io/xclang/blob/main/patches/0013-runtime-dir-pc-vendor/README.md" target="_blank" rel="noreferrer"><code>0013-runtime-dir-pc-vendor</code></a></td><td><code>--target=x86_64-pc-linux-gnu</code> and <code>x86_64-pc-windows-gnu</code>, GCC&#39;s spellings, and <code>arm64-linux-gnu</code> and <code>arm64-w64-mingw32</code> find compiler-rt under the usual spelling: they link</td></tr><tr><td><a href="https://github.com/clice-io/xclang/blob/main/patches/0014-coff-timestamp-default/README.md" target="_blank" rel="noreferrer"><code>0014-coff-timestamp-default</code></a></td><td>COFF objects for MinGW targets have no compile time in their header again, as in LLVM 22 and GNU tools: the same source gives the same object (llvm/llvm-project#222099)</td></tr><tr><td><a href="https://github.com/clice-io/xclang/blob/main/patches/0016-libcxx-vcruntime/README.md" target="_blank" rel="noreferrer"><code>0016-libcxx-vcruntime</code></a></td><td>libc++ on vcruntime defines no <code>std::nothrow</code>, the C runtime&#39;s, and defines <code>std::set_new_handler</code> and <code>get_new_handler</code>, which only Microsoft&#39;s STL library did</td></tr><tr><td><a href="https://github.com/clice-io/xclang/blob/main/patches/0017-lld-coff-call-graph-order/README.md" target="_blank" rel="noreferrer"><code>0017-lld-coff-call-graph-order</code></a></td><td>lld-link lays out a PGO-built program the same way on every link: local functions of the same name in several objects no longer move from one link to the next</td></tr><tr><td><a href="https://github.com/clice-io/xclang/blob/main/patches/0018-stdlib-system-config/README.md" target="_blank" rel="noreferrer"><code>0018-stdlib-system-config</code></a></td><td>a <code>-stdlib=</code> of another library than libc++ (<code>platform</code>, <code>libstdc++</code>; clang-cl <code>/clang:-stdlib=platform</code>) selects the target&#39;s <code>&lt;triple&gt;-system.cfg</code>: the platform&#39;s C++ library, and its sysroot, on every target (<a href="./../guide/cross-compiling#the-platform-s-c-library">the system&#39;s C++ library</a>)</td></tr></tbody></table><h2 id="how-they-are-applied" tabindex="-1">How They Are Applied <a class="header-anchor" href="#how-they-are-applied" aria-label="Permalink to &quot;How They Are Applied&quot;">​</a></h2><p><code>toolchain/common.ts</code> applies every <code>patches/NNNN-name/NNNN.patch</code>, in the order of the directories, right after it unpacks LLVM&#39;s source, with <code>patch -p1 -F0 --forward</code>: without fuzz, so a patch applies where it was made or the build fails. The runtimes&#39; sources that every toolchain carries in <code>libc++/src</code> get the same patches, those of their files (<a href="./../features/runtimes-from-source">runtimes from source</a>). libclang&#39;s <code>lib/cmake/xclang/libclang.cmake</code> lists the series in <code>XCLANG_PATCHES</code> (<a href="./cmake-api">CMake API</a>).</p><h2 id="what-a-patch-has" tabindex="-1">What a Patch Has <a class="header-anchor" href="#what-a-patch-has" aria-label="Permalink to &quot;What a Patch Has&quot;">​</a></h2><ul><li>A directory <code>patches/NNNN-short-name/</code> with one <code>NNNN.patch</code>, a <code>git diff</code> against LLVM&#39;s release tag, and a <code>README.md</code>: what goes wrong and who hits it, what the patch changes, its state upstream (<code>Upstream:</code>), where it came from (<code>From:</code>) and how it was checked (<code>Checked:</code>).</li><li>A check that fails without it, in <code>tests/toolchain/smoke.ts</code> (every host&#39;s toolchain), <code>tests/cmake</code> or <code>tests/bazel</code>.</li><li>A number that is never reused: a patch that upstream took is deleted with the LLVM release that has it.</li></ul>',8)])])}const g=t(o,[["render",i]]);export{m as __pageData,g as default};
